export const meta = {
  name: 'review-panel',
  description: 'Review a diff through several lenses, then try to refute each important finding',
  phases: [{ title: 'Lenses' }, { title: 'Skeptics' }],
}

const FINDINGS = { type: 'object', required: ['findings'], properties: { findings: { type: 'array', items: {
  type: 'object', required: ['path', 'line', 'severity', 'body'], properties: {
    path: { type: 'string' }, line: { type: 'integer' }, severity: { enum: ['important', 'nit'] }, body: { type: 'string' } } } } } }
const VERDICT = { type: 'object', required: ['refuted'], properties: { refuted: { type: 'boolean' } } }
const LENSES = ['correctness', 'security', 'tests']

phase('Lenses')
const found = await parallel(LENSES.map((lens) => () =>
  agent(`Review the diff in ${args.diffPath} through the ${lens} lens.`, { schema: FINDINGS, label: lens })))

const important = found.filter(Boolean).flatMap((r) => r.findings).filter((f) => f.severity === 'important')

phase('Skeptics')
const checked = await parallel(important.map((f) => () =>
  agent(`Try to refute this finding. Read ${f.path}:${f.line}. If you cannot show the problem, refuted=true.\n${f.body}`,
    { schema: VERDICT, label: `${f.path}:${f.line}` })))

const kept = important.filter((f, i) => checked[i] && !checked[i].refuted)
log(`${kept.length} of ${important.length} important findings survived`)
return { findings: kept }

import { query } from "@anthropic-ai/claude-agent-sdk";

for await (const msg of query({
  prompt: "Run the saved workflow review-panel with args { diffPath: 'diff.patch' } and report the findings that survived.",
  options: {
    model: "claude-opus-5-5",
    effort: "medium",
    tools: ["Read", "Grep", "Glob", "Workflow"],
    allowedTools: ["Read", "Grep", "Glob", "Workflow"],
    permissionMode: "dontAsk",
    settings: { workflowSizeGuideline: "small" },
    env: { ...process.env, CLAUDE_CODE_WORKFLOW_MAX_CONCURRENT_AGENTS: "3" },
  },
})) {
  if (msg.type === "result") {
    for (const [model, use] of Object.entries(msg.modelUsage)) console.log(model, "$" + use.costUSD.toFixed(4));
    if (msg.subtype === "success") console.log(msg.result);
  }
}

