  agents++;
  const label = opts.label ?? prompt.slice(0, 30);
  const answer = answers[label] ?? null; // a missing answer behaves like a stopped or failed agent
  console.log(`  agent ${String(agents).padStart(2)}  ${label.padEnd(22)} -> ${answer === null ? "null" : "answered"}`);
