export const meta = {
  name: 'review-panel',
  description: 'Review a diff through several lenses, then try to refute each important finding',
  phases: [{ title: 'Lenses' }, { title: 'Skeptics' }],
}

const FINDINGS = { type: 'object', required: ['findings'], properties: { findings: { type: 'array', items: {
  type: 'object', required: ['path', 'line', 'severity', 'body'], properties: {
    path: { type: 'string' }, line: { type: 'integer' }, severity: { enum: ['important', 'nit'] }, body: { type: 'string' } } } } } }
const VERDICT = { type: 'object', required: ['refuted'], properties: { refuted: { type: 'boolean' } } }
const LENSES = ['correctness', 'security', 'tests']

const reviewed = await pipeline(LENSES,
  (lens) => agent(`Review the diff in ${args.diffPath} through the ${lens} lens.`, { schema: FINDINGS, label: lens }),
  (found) => parallel((found?.findings ?? []).filter((f) => f.severity === 'important').map((f) => () =>
    agent(`Try to refute this finding. Read ${f.path}:${f.line}. If you cannot show the problem, refuted=true.\n${f.body}`,
      { schema: VERDICT, label: `${f.path}:${f.line}` }).then((v) => (v && !v.refuted ? f : null)))))

const kept = reviewed.flat().filter(Boolean)
log(`${kept.length} important findings survived`)
return { findings: kept }
